import React from 'react';
import './PaymentPartner.css'; 

const PaymentPartner = () => {
    const partners = [
        {
            name: '',
            logo: 'https://upload.wikimedia.org/wikipedia/commons/f/ff/Esewa_logo.webp',
            desc: 'Nepal\'s first and leading online payment gateway.'
        },
        {
            name: 'Khalti',
            logo: '',
            desc: 'An easy-to-use digital wallet for all your payments.'
        },
        {
            name: 'ConnectIPS',
            logo: 'https://www.connectips.com/images/connectips-logo.png',
            desc: 'Single platform for direct bank-to-bank transfers.'
        },
        
    ];

    return (
        <section className="partner-section">
            <div className="container">
                <h2>Digital Payment Partners</h2>
                <div className="partner-grid">
                    {partners.map((partner, index) => (
                        <div className="partner-card" key={index}>
                            <img 
                                src={partner.logo} 
                                alt={partner.name} 
                                onError={(e) => {e.target.src = 'https://via.placeholder.com/150?text=Payment+Partner'}}
                            />
                            <h3>{partner.name}</h3>
                            <p>{partner.desc}</p>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default PaymentPartner;
